INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q3280731', 'Mexican Indian Wars', 'Indigenous rebellions in Mexico and Central America were conflicts of resistance initiated by American Indian peoples against European colonial empires and their succeeding nation settler states that occurred in the territory of the continental Viceroyalty of New Spain and British Honduras, as well as their respective successor states. The latter include Mexico, Guatemala, Honduras, Belize, El Salvador, Nicaragua, Costa Rica, and parts of the Southern and Western United States.', 1519, NULL, NULL, 1933, NULL, NULL, 'year', '1519–1933', 45, 'https://en.wikipedia.org/wiki/List_of_Indigenous_rebellions_in_Mexico_and_Central_America'),
  ('Q1131442', 'Massacre in the Great Temple of Tenochtitlan', 'The Massacre in the Great Temple, also called the Toxcatl Massacre, or the Alvarado Massacre, was an event on 22 May 1520, in the Mexica, also known as the Aztec, capital of Tenochtitlan during the Spanish conquest of the Aztec Empire, in which the celebration of the Feast of Toxcatl ended in a massacre of Mexica elites. In late April of 1520, Cuban Governor Diego Velázquez de Cuéllar ordered Spanish conquistador, Pánfilo de Narváez, to arrest Hernán Cortés while he was in Tenochtitlan.', 1520, 5, 22, NULL, NULL, NULL, 'day', '22 May 1520', 50, 'https://en.wikipedia.org/wiki/Massacre_in_the_Great_Temple_of_Tenochtitlan'),
  ('Q1308854', 'La Noche Triste', 'La Noche Triste ("The Night of Sorrows", literally "The Sad Night"), officially called in Mexico Victorious Night, was an important event during the Spanish conquest of the Aztec Empire, where Hernán Cortés and his army of Spanish conquistadors, including their native allies were driven out of the Mexica capital, Tenochtitlan.', 1520, 6, 30, 1520, 7, 1, 'day', '30 June 1520 – 1 July 1520', 65, 'https://en.wikipedia.org/wiki/La_Noche_Triste'),
  ('Q2888038', 'Battle of Otumba', 'The Battle of Otumba was a major battle fought on 7 July 1520 between the Aztec Empire and its allies led by the Cihuacoatl Matlatzincátzin, and Spanish conquistadors under Hernán Cortés, alongside support from the Confederacy of Tlaxcala. The battle was fought on the plain of Temalcatitlán, near modern-day Otumba during the conquest of the Aztec Empire by Spain.', 1520, 7, 7, NULL, NULL, NULL, 'day', '7 July 1520', 52, 'https://en.wikipedia.org/wiki/Battle_of_Otumba'),
  ('Q593267', 'Fall of Tenochtitlan', 'The fall of Tenochtitlan, the capital of the Mexica, was an important event in the Spanish conquest of the Mexica. It occurred in 1521 following extensive negotiations between local factions and Spanish conquistador Hernán Cortés.', 1521, 5, 10, 1521, 8, 13, 'day', '10 May 1521 – 13 August 1521', 61, 'https://en.wikipedia.org/wiki/Fall_of_Tenochtitlan'),
  ('Q2889912', 'Battle of San Juan de Ulúa', 'The Battle of San Juan de Ulúa was fought between English privateers and Spanish forces at San Juan de Ulúa (in modern Veracruz, Mexico). The English flotilla of six armed merchant ships under John Hawkins had been trading along the Spanish Main with the cooperation of local Spanish officials.', 1568, 9, 23, NULL, NULL, NULL, 'day', '23 September 1568', 45, 'https://en.wikipedia.org/wiki/Battle_of_San_Juan_de_Ul%C3%BAa_(1568)'),
  ('Q68750', 'Mexican War of Independence', 'The Mexican War of Independence (Spanish: Guerra de Independencia de México, 16 September 1810 – 27 September 1821) was an armed conflict and political movement that eventually resulted in Mexico''s independence from the Spanish Empire. It was not a single, coherent event, but local and regional struggles that occurred within the same period, and can be considered a revolutionary civil war.', 1800, 9, 16, 1821, 9, 27, 'day', '16 September 1800 – 27 September 1821', 76, 'https://en.wikipedia.org/wiki/Mexican_War_of_Independence'),
  ('Q1145411', 'Grito de Dolores', 'The Cry of Dolores (Spanish: Grito de Dolores) occurred in Dolores, Mexico, on 16 September 1810, when Roman Catholic priest Miguel Hidalgo y Costilla rang his church bell and gave the call to arms that triggered the Mexican War of Independence. The Cry of Dolores is most commonly known by the locals as El Grito de Independencia (The Independence Cry).', 1810, 9, 16, NULL, NULL, NULL, 'day', '16 September 1810', 64, 'https://en.wikipedia.org/wiki/Grito_de_Dolores'),
  ('Q2268588', 'Solemn Act of the Declaration of Independence of Northern America', 'The Solemn Act of Northern America''s Declaration of Independence (Spanish: Acta Solemne de la Declaración de Independencia de la América Septentrional) is the first Mexican legal historical document which established the separation of Mexico from Spanish rule. It was signed on November 6, 1813, by the deputies of the Congress of Anáhuac, organized by General José María Morelos in the city of Oaxaca in June of that same year, and later installed in the city of Chilpancingo on September 13.', 1813, 11, 6, NULL, NULL, NULL, 'day', '6 November 1813', 43, 'https://en.wikipedia.org/wiki/Solemn_Act_of_the_Declaration_of_Independence_of_Northern_America'),
  ('Q767450', 'Treaty of Córdoba', 'The Treaty of Córdoba established Mexican independence from Spain at the conclusion of the Mexican War of Independence. It was signed on August 24, 1821 in Córdoba, Veracruz, Mexico.', 1821, 8, 24, 1822, 2, NULL, 'day', '24 August 1821 – February 1822', 53, 'https://en.wikipedia.org/wiki/Treaty_of_C%C3%B3rdoba'),
  ('Q1131780', 'Declaration of Independence of the Mexican Empire', 'The Declaration of Independence of the Mexican Empire (Spanish: Acta de Independencia del Imperio Mexicano) is the document by which Mexico declared independence from the Spanish Empire. This founding document of the Mexican nation was drafted in the National Palace in Mexico City on 28 September 1821, by Juan José Espinosa de los Monteros, secretary of the Provisional Governmental Board.', 1821, 9, 28, NULL, NULL, NULL, 'day', '28 September 1821', 47, 'https://en.wikipedia.org/wiki/Declaration_of_Independence_(Mexico)'),
  ('Q1606520', 'Plan of ayala', 'The Plan of Iguala, also known as the Plan of the Three Guarantees ("Plan Trigarante") or Act of Independence of North America, was a revolutionary proclamation promulgated on 24 February 1821, in the final stage of the Mexican War of Independence from Spain. The Plan stated that Mexico was to become a constitutional monarchy, whose sole official religion would be Roman Catholicism, in which both the Peninsulares (people born in Spain and residing in Mexico) and the Americanos (people born in Mexico, that is, the Americas) would enjoy equal political and social rights.', 1821, 2, 24, NULL, NULL, NULL, 'day', '24 February 1821', 55, 'https://en.wikipedia.org/wiki/Plan_of_Iguala'),
  ('Q2508152', 'Fredonian Rebellion', 'The Fredonian Rebellion or Texan revolt of 1826 (December 21, 1826 – January 31, 1827) was the first attempt by Texans to secede from Mexico. The settlers, led by Empresario Haden Edwards, declared independence from Mexican Texas and created the Republic of Fredonia near Nacogdoches.', 1826, 12, 21, 1827, 1, 31, 'day', '21 December 1826 – 31 January 1827', 47, 'https://en.wikipedia.org/wiki/Fredonian_Rebellion'),
  ('Q1361674', 'Treaties of Velasco', 'The Treaties of Velasco (Spanish: Tratados de Velasco) were two documents, one private and the other public, signed in Fort Velasco on May 14, 1836 between General Antonio López de Santa Anna and the Republic of Texas in the aftermath of the Battle of San Jacinto on April 21, 1836. The fort was located in the former Velasco, Texas, now part of the present-day location of Surfside Beach.', 1836, 5, 14, NULL, NULL, NULL, 'day', '14 May 1836', 45, 'https://en.wikipedia.org/wiki/Treaties_of_Velasco'),
  ('Q856168', 'Pastry War', 'The Pastry War began in November 1838 when French naval forces blockaded ports in Mexico, and captured San Juan de Ulúa in Veracruz. This was in response to allegations of mistreatment of French nationals in Mexico, including a pastry chef after whom the war was named, and ended in March 1839 with a British-brokered peace.', 1838, 11, 27, 1839, 3, 9, 'day', '27 November 1838 – 9 March 1839', 65, 'https://en.wikipedia.org/wiki/Pastry_War'),
  ('Q1628057', 'Battle of Monterrey', 'In the Battle of Monterrey (September 21–24, 1846) during the Mexican–American War, General Pedro de Ampudia and the Mexican Army of the North was defeated by the Army of Occupation, a force of United States Regulars, Volunteers, and Texas Rangers under the command of General Zachary Taylor. The hard-fought urban combat led to heavy casualties on both sides.', 1846, NULL, NULL, 1846, 9, 24, 'year', '1846', 55, 'https://en.wikipedia.org/wiki/Battle_of_Monterrey'),
  ('Q1536618', 'Battle of Chapultepec', 'The Battle of Chapultepec took place between U.S. troops and Mexican forces holding the strategically located Chapultepec Castle on the outskirts of Mexico City on September 13, 1847 during the Mexican–American War. The castle was built atop a 200-foot (61 m) hill in 1783, and in 1833 it was converted into a military academy and a gunpowder storage facility.', 1847, NULL, NULL, 1847, 9, 13, 'year', '1847', 57, 'https://en.wikipedia.org/wiki/Battle_of_Chapultepec'),
  ('Q1808450', 'Battle of Buena Vista', 'The Battle of Buena Vista (February 22–23, 1847), known as the Battle of La Angostura in Mexico, and sometimes as Battle of Buena Vista/La Angostura, was a battle of the Mexican–American War. It was fought between U.S. forces, largely volunteers, under General Zachary Taylor, and the much larger Mexican Army under General Antonio López de Santa Anna.', 1847, NULL, NULL, 1847, 2, 23, 'year', '1847', 51, 'https://en.wikipedia.org/wiki/Battle_of_Buena_Vista'),
  ('Q2333407', 'Battle of Churubusco', 'The Battle of Churubusco took place on August 20, 1847, while Santa Anna''s army was in retreat from the Battle of Contreras during the Mexican–American War. It was the battle where the San Patricio Battalion, made up largely of US deserters, made their last stand against U.S. forces.', 1847, 8, 20, NULL, NULL, NULL, 'day', '20 August 1847', 48, 'https://en.wikipedia.org/wiki/Battle_of_Churubusco'),
  ('Q2399696', 'Battle of Contreras', 'The Battle of Contreras, also known as the Battle of Padierna, took place on 19–20 August 1847, in one of the final encounters of the Mexican–American War, as invading U.S. forces under Winfield Scott approached the Mexican capital. American forces surprised and then routed the Mexican forces of General Gabriel Valencia, who had disobeyed General Antonio López de Santa Anna''s orders for his forces'' placement.', 1847, 8, 20, NULL, NULL, NULL, 'day', '20 August 1847', 47, 'https://en.wikipedia.org/wiki/Battle_of_Contreras'),
  ('Q2689975', 'Battle of Molino del Rey', 'The Battle of Molino del Rey (8 September 1847) was one of the bloodiest engagements of the Mexican–American War as part of the Battle for Mexico City. It was fought in September 1847 between Mexican forces under General Antonio León against an American force under Major General Winfield Scott at El Molino del Rey on the fringes of Mexico City.', 1847, 9, 8, NULL, NULL, NULL, 'day', '8 September 1847', 47, 'https://en.wikipedia.org/wiki/Battle_of_Molino_del_Rey'),
  ('Q2745368', 'Siege of Veracruz', 'On 9 March 1847, during the Mexican–American War, the United States military made an amphibious landing and besieged the key Mexican seaport of Veracruz. The port surrendered twenty days later.', 1847, NULL, NULL, 1847, 3, 29, 'year', '1847', 52, 'https://en.wikipedia.org/wiki/Siege_of_Veracruz'),
  ('Q616109', 'Treaty of Guadalupe Hidalgo', 'The Treaty of Guadalupe Hidalgo officially ended the Mexican–American War (1846–1848). It was signed on the 2nd of February 1848 in the town of Guadalupe Hidalgo.', 1848, 2, 2, NULL, NULL, NULL, 'day', '2 February 1848', 71, 'https://en.wikipedia.org/wiki/Treaty_of_Guadalupe_Hidalgo'),
  ('Q827212', 'Gadsden Purchase', 'The Gadsden Purchase (Spanish: Venta de La Mesilla, lit. ''La Mesilla sale''), also known as the Treaty of Mesilla, is the acquisition of a 29,640-square-mile (76,800 km2) region of present-day southern Arizona and southwestern New Mexico by the United States from Mexico. The first draft was signed on December 31, 1853, by James Gadsden, US Minister to Mexico, and by Antonio López de Santa Anna, president of Mexico.', 1853, NULL, NULL, NULL, NULL, NULL, 'year', '1853', 69, 'https://en.wikipedia.org/wiki/Gadsden_Purchase'),
  ('Q2091916', 'Reform War', 'The Reform War (17 December 1857 – 11 January 1861) or War of Reform (Spanish: Guerra de Reforma), also known as the Three Years'' War (Spanish: Guerra de los Tres Años) and the Mexican Civil War, was a complex civil conflict in Mexico that was fought between Mexican liberals and conservatives with regional variations over the promulgation of the Constitution of 1857. It has been called the "worst civil war to hit Mexico between the War of Independence of 1810–21 and the Revolution of 1910–20." Following the liberals'' overthrow of the dictatorship of the conservative Antonio López de Santa…', 1861, NULL, NULL, 1861, 1, 10, 'century', '19th century', 59, 'https://en.wikipedia.org/wiki/Reform_War'),
  ('Q1061228', 'Battle of Puebla', 'The Battle of Puebla (Spanish: Batalla de Puebla; French: Bataille de Puebla), also known as the Battle of the Fifth of May (Spanish: Batalla del Cinco de Mayo) took place on 5 May 1862, near Puebla de los Ángeles, during the second French intervention in Mexico. French troops under the command of Charles de Lorencez repeatedly failed to storm the forts of Loreto and Guadalupe situated on top of the hills overlooking the city of Puebla, and eventually retreated to Orizaba in order to await reinforcements.', 1862, 5, 5, NULL, NULL, NULL, 'day', '5 May 1862', 65, 'https://en.wikipedia.org/wiki/Battle_of_Puebla'),
  ('Q399224', 'Battle of Camarón', 'The Battle of Camarón (French: Bataille de Camerone) was a last stand engagement fought on 30 April 1863 between the French Foreign Legion and the Mexican Army, during the Second French intervention in Mexico (1861–1867). A small French detachment of 65 men, led by Captain Jean Danjou, was escorting a supply convoy when it was surrounded near the village of Camarón de Tejeda in Veracruz by a force of around 2,000 Mexican troops.', 1863, 4, 30, NULL, NULL, NULL, 'day', '30 April 1863', 57, 'https://en.wikipedia.org/wiki/Battle_of_Camar%C3%B3n'),
  ('Q214426', 'Mexican Revolution', 'The Mexican Revolution (Spanish: Revolución mexicana) was an extended sequence of armed regional conflicts in Mexico from 20 November 1910 to 1 December 1920. It has been called "the defining event of modern Mexican history".', 1910, 11, 20, 1920, 5, 21, 'day', '20 November 1910 – 21 May 1920', 80, 'https://en.wikipedia.org/wiki/Mexican_Revolution'),
  ('Q1187198', 'Ten Tragic Days', 'The Ten Tragic Days (Spanish: La Decena Trágica) is the name given to the multi-day coup d''état during the Mexican Revolution in Mexico City. It was staged by opponents of Francisco I. Madero, the democratically elected president of Mexico, between 9–19 February 1913.', 1913, 2, 19, NULL, NULL, NULL, 'day', '19 February 1913', 52, 'https://en.wikipedia.org/wiki/Ten_Tragic_Days'),
  ('Q1316711', 'Battle of Veracruz', 'The Battle of Veracruz was a military conflict between the United States and Mexico that took place in the Mexican port city of Veracruz between April 21 to November 23, 1914. The incident occurred in the midst of tense diplomatic relations between Mexico and the United States related to the ongoing Mexican Revolution.', 1914, 11, NULL, 1914, 11, NULL, 'month', 'November 1914', 57, 'https://en.wikipedia.org/wiki/Battle_of_Veracruz_(1914)'),
  ('Q1848264', 'Battle of Zacatecas', 'The Battle of Zacatecas, also known as the Toma de Zacatecas ("Taking of Zacatecas"), was the bloodiest battle in the campaign to overthrow Mexican President Victoriano Huerta. On June 23, 1914, Pancho Villa''s División del Norte (Division of the North) decisively defeated the federal troops of General Luis Medina Barrón defending the town of Zacatecas.', 1914, 6, 23, NULL, NULL, NULL, 'day', '23 June 1914', 43, 'https://en.wikipedia.org/wiki/Battle_of_Zacatecas_(1914)'),
  ('Q279662', 'Cristero War', 'The Cristero War (Spanish: La guerra cristera), also known as the Cristero Rebellion or La Cristiada [la kɾisˈtjaða], was a widespread struggle in central and western Mexico from 3 August 1926 to 21 June 1929 in response to the implementation of secularist and anticlerical articles of the 1917 Constitution. The rebellion was instigated as a response to an executive decree by Mexican President Plutarco Elías Calles to strictly enforce Article 130 of the Constitution, an implementing act known as the Calles Law.', 1926, NULL, NULL, 1929, 6, 21, 'year', '1926 – 21 June 1929', 67, 'https://en.wikipedia.org/wiki/Cristero_War'),
  ('Q5579119', 'Golden Age of Mexican cinema', 'The Golden Age of Mexican Cinema (Spanish: Época de Oro del Cine Mexicano) was a boom period in the history of Mexican cinema, which began in 1936 with the premiere of the film Allá en el Rancho Grande, and culminated in 1956. In 1939, during World War II, the film industry in the US and Europe declined, because the materials previously destined for film production now were for the new arms industry.', 1936, NULL, NULL, 1956, NULL, NULL, 'year', '1936–1956', 50, 'https://en.wikipedia.org/wiki/Golden_Age_of_Mexican_Cinema'),
  ('Q909737', 'Tlatelolco massacre', 'The Tlatelolco massacre (Spanish: Masacre de Tlatelolco) was a military massacre committed by the Mexican Armed Forces against the students of the National Autonomous University of Mexico (UNAM), the National Polytechnic Institute (IPN) and other universities in Mexico. The massacre followed a series of large demonstrations known as the Mexican Movement of 1968 and is considered part of the Mexican Dirty War when the U.S.-backed Institutional Revolutionary Party (PRI) government violently repressed political and social opposition.', 1968, 10, 2, NULL, NULL, NULL, 'day', '2 October 1968', 64, 'https://en.wikipedia.org/wiki/Tlatelolco_massacre'),
  ('Q1890705', '1968 Olympics Black Power salute', 'During their medal ceremony in the Olympic Stadium in Mexico City on October 16, 1968, two African-American athletes, Tommie Smith and John Carlos, each raised a black-gloved fist during the playing of the US national anthem, "The Star-Spangled Banner". While on the podium, Smith and Carlos, who had won gold and bronze medals respectively in the 200-meter running event of the 1968 Summer Olympics, turned to face the US flag and then kept their hands raised until the anthem had finished.', 1968, 10, 16, NULL, NULL, NULL, 'day', '16 October 1968', 58, 'https://en.wikipedia.org/wiki/1968_Olympics_Black_Power_salute'),
  ('Q3562580', 'Flight 2605 by Western Airlines', 'Western Airlines Flight 2605, nicknamed the "Night Owl", was an international scheduled passenger flight from Los Angeles, California, to Mexico City, Mexico. On October 31, 1979, at 5:42 a.m.', 1979, 10, 31, NULL, NULL, NULL, 'day', '31 October 1979', 45, 'https://en.wikipedia.org/wiki/Western_Airlines_Flight_2605'),
  ('Q4688331', 'Aeroméxico Flight 230', 'On July 27, 1981, Aeroméxico Flight 230, operating a domestic passenger flight within Mexico, experienced a hard landing and runway excursion at Chihuahua International Airport. Thirty-two people were killed in the accident.', 1981, 7, 27, NULL, NULL, NULL, 'day', '27 July 1981', 45, 'https://en.wikipedia.org/wiki/Aerom%C3%A9xico_Flight_230'),
  ('Q1629818', 'San Juanico disaster', 'The San Juanico disaster was a series of deadly fires and explosions that occurred at a Pemex-owned liquefied petroleum gas (LPG) terminal on 19 November 1984, in San Juan Ixhuatepec, a town of Tlalnepantla de Baz, within the State of Mexico, Mexico. The fires and explosions were caused by the rupturing of a pipeline within the facility, which released vaporized LPG that ignited and damaged several storage tanks.', 1984, 11, 19, NULL, NULL, NULL, 'day', '19 November 1984', 45, 'https://en.wikipedia.org/wiki/San_Juanico_disaster'),
  ('Q1798567', '1985 Mexico City earthquake', 'The 1985 Mexico City earthquake struck in the early morning of 19 September at 07:17:50 (CST) with a moment magnitude of 8.0 and a maximal Mercalli intensity of IX (Violent). The event caused serious damage to the Greater Mexico City area and the deaths of at least 5,000 people.', 1985, 9, 19, NULL, NULL, NULL, 'day', '19 September 1985', 65, 'https://en.wikipedia.org/wiki/1985_Mexico_City_earthquake'),
  ('Q2381192', 'Mexicana de Aviación Flight 940', 'Mexicana de Aviación Flight 940 was a scheduled international flight from Mexico City to Los Angeles with stopovers in Puerto Vallarta and Mazatlán. On March 31, 1986, the Boeing 727 Veracruz, registered as XA-MEM, crashed into El Carbón, a mountain in the Sierra Madre Occidental mountain range northwest of Mexico City.', 1986, 3, 31, NULL, NULL, NULL, 'day', '31 March 1986', 58, 'https://en.wikipedia.org/wiki/Mexicana_de_Aviaci%C3%B3n_Flight_940'),
  ('Q377665', '1992 Guadalajara explosions', 'A series of ten explosions took place on April 22, 1992, in the downtown district of Analco Colonia Atlas in Guadalajara city, Jalisco state, Mexico. Numerous gasoline explosions in the sewer system and fires over four hours destroyed 8 kilometres (5.0 mi) of streets.', 1992, 4, 22, NULL, NULL, NULL, 'day', '22 April 1992', 52, 'https://en.wikipedia.org/wiki/1992_Guadalajara_explosions'),
  ('Q1143976', 'female homicides in Ciudad Juárez, organize crime, immigration', 'More than 500 women were killed between 1993 and 2011 in Ciudad Juárez, a city in northern Mexico. The murders of women and girls received international attention primarily due to perceived government inaction in preventing the violence and bringing perpetrators to justice.', 1993, NULL, NULL, NULL, NULL, NULL, 'year', '1993', 50, 'https://en.wikipedia.org/wiki/Femicide_in_Ciudad_Ju%C3%A1rez'),
  ('Q2578008', 'Acteal massacre', 'The Acteal massacre (Spanish: Matanza de Acteal) was a massacre of 45 people attending a prayer meeting of Catholic Indigenous townspeople, including a number of children and pregnant women, who were members of the pacifist group Las Abejas ("The Bees"), in the small village of Acteal in the municipality of Chenalhó, in the Mexican state of Chiapas. Right-wing paramilitary group Máscara Roja murdered the victims on December 22, 1997, while the Government of Mexico first admitted responsibility for the massacre in September 2020.', 1997, 12, 22, NULL, NULL, NULL, 'day', '22 December 1997', 47, 'https://en.wikipedia.org/wiki/Acteal_massacre'),
  ('Q786657', 'Battle of Calderón Bridge', 'The Battle of Calderón Bridge (Spanish: Batalla del Puente de Calderón) was a decisive battle in the Mexican War of Independence. It was fought in January 1811 on the banks of the Calderón River 60 km (37 mi) east of Guadalajara in present-day Zapotlanejo, Jalisco.', 2000, 1, 17, NULL, NULL, NULL, 'day', '17 January 2000', 41, 'https://en.wikipedia.org/wiki/Battle_of_Calder%C3%B3n_Bridge'),
  ('Q3497601', '2003 Colima earthquake', 'An earthquake struck the Pacific Coast of Mexico on 21 January 2003 with a moment magnitude of 7.5. It had a maximum Mercalli intensity of VIII (Severe).', 2003, 1, 21, NULL, NULL, NULL, 'day', '21 January 2003', 41, 'https://en.wikipedia.org/wiki/2003_Colima_earthquake'),
  ('Q1090887', '2006 Oaxaca protests', 'The Mexican state of Oaxaca was embroiled in a conflict that lasted more than seven months and resulted in at least seventeen deaths and the occupation of the capital city of Oaxaca by the Popular Assembly of the Peoples of Oaxaca (APPO). The conflict emerged in May 2006 with the police responding to a strike involving the local teachers'' trade union by opening fire on non-violent protests.', 2006, NULL, NULL, NULL, NULL, NULL, 'year', '2006', 47, 'https://en.wikipedia.org/wiki/2006_Oaxaca_rebellion'),
  ('Q2707543', '2008 Mexico City Learjet crash', 'On 4 November 2008, a Learjet 45 carrying Mexican Secretary of the Interior Juan Camilo Mouriño, crashed into rushhour traffic in central Mexico City at around 18:45 local time. The crash resulted in the deaths of 16 people, all nine people on board and seven people on the ground.', 2008, 11, 4, NULL, NULL, NULL, 'day', '4 November 2008', 52, 'https://en.wikipedia.org/wiki/2008_Mexico_City_Learjet_45_crash'),
  ('Q1538397', '2010 Baja California earthquake', 'The 2010 Baja California earthquake (also known as 2010 Easter earthquake, 2010 Sierra El Mayor earthquake, or 2010 El Mayor–Cucapah earthquake) occurred on April 4 (Easter Sunday) with a moment magnitude of 7.2 and a maximum Mercalli intensity of IX (Violent). The shock originated at 15:40:41 local time (3:40:41 PM PDT) south of Guadalupe Victoria, Baja California, Mexico.', 2010, 4, 4, NULL, NULL, NULL, 'day', '4 April 2010', 52, 'https://en.wikipedia.org/wiki/2010_Baja_California_earthquake'),
  ('Q1553270', '2012 Guerrero–Oaxaca earthquake', 'The 2012 Guerrero–Oaxaca earthquake struck southern Mexico with a moment magnitude of 7.4 at 12:02 local time on Tuesday, 20 March. Its epicenter was near Ometepec, in the border between the states of Guerrero and Oaxaca.', 2012, 3, 20, NULL, NULL, NULL, 'day', '20 March 2012', 50, 'https://en.wikipedia.org/wiki/2012_Guerrero%E2%80%93Oaxaca_earthquake'),
  ('Q28043392', '2016 San Pablito Market fireworks explosion', 'On 20 December 2016, a fireworks accident occurred at the San Pablito Market in the city of Tultepec, north of Valley of Mexico. At least 42 people were killed in the explosion, and dozens injured.', 2016, 12, 20, NULL, NULL, NULL, 'day', '20 December 2016', 53, 'https://en.wikipedia.org/wiki/2016_San_Pablito_Market_fireworks_explosion'),
  ('Q38982786', '2017 Oaxaca and Chiapas Earthquake', 'The 2017 Chiapas earthquake struck at 23:49 CDT on 7 September (local time; 04:49 on the 8th UTC) in the Gulf of Tehuantepec off the southern coast of Mexico near the state of Chiapas, approximately 87 kilometres (54 mi) southwest of Pijijiapan (alternately, 101 kilometres (63 mi) south-southwest of Tres Picos), with a Mercalli intensity of IX (Violent). The moment magnitude was estimated to be Mw 8.2.', 2017, 9, 7, NULL, NULL, NULL, 'day', '7 September 2017', 68, 'https://en.wikipedia.org/wiki/2017_Chiapas_earthquake'),
  ('Q40355642', '2017 Central Mexico earthquake', 'The 2017 Puebla earthquake, also known as 19S, struck at 13:14 CDT (18:14 UTC) on 19 September 2017 with an estimated magnitude of 7.1 Mw and strong shaking for about 20 seconds. Its epicenter was about 55 km (34 mi) south of the city of Puebla, Mexico.', 2017, 9, 19, NULL, NULL, NULL, 'day', '19 September 2017', 66, 'https://en.wikipedia.org/wiki/2017_Puebla_earthquake'),
  ('Q48936616', '2018 Oaxaca earthquake', 'The 2018 Oaxaca earthquake occurred on February 16, 2018, at 17:39 local time (23:39 UTC) in the Sierra Madre del Sur mountains in Oaxaca state in Southern Mexico. It had a magnitude of 7.2 on the moment magnitude scale and a maximum felt intensity of VII (Very strong) on the Mercalli intensity scale.', 2018, 2, 14, NULL, NULL, NULL, 'day', '14 February 2018', 48, 'https://en.wikipedia.org/wiki/2018_Oaxaca_earthquake'),
  ('Q51343073', 'Migrant''s Way of the Cross', 'Central American migrant caravans, also known as the Viacrucis del migrante ("Migrant''s Way of the Cross"), are migrant caravans that travel from Central America to the Mexico–United States border to seek asylum in the United States. The largest and best known of these were organized by Pueblo Sin Fronteras (A People Without Borders) that set off during Holy Week in early 2017 and 2018 from the Northern Triangle of Central America (NTCA), but such caravans of migrants began arriving several years earlier, and other unrelated caravans continued to arrive into late 2018.', 2018, NULL, NULL, NULL, NULL, NULL, 'year', '2018', 51, 'https://en.wikipedia.org/wiki/Central_American_migrant_caravans'),
  ('Q55859110', 'Aeroméxico Connect Flight 2431', 'Aeroméxico Connect Flight 2431 was a Mexican domestic scheduled passenger flight bound for Mexico City that crashed on takeoff from Durango International Airport on July 31, 2018. Shortly after becoming airborne, the plane encountered sudden wind shear caused by a microburst.', 2018, 7, 31, NULL, NULL, NULL, 'day', '31 July 2018', 50, 'https://en.wikipedia.org/wiki/Aerom%C3%A9xico_Connect_Flight_2431'),
  ('Q60683841', 'Tlahuelilpan pipeline explosion', 'On 18 January 2019, a pipeline transporting gasoline exploded in the town of Tlahuelilpan, in the Mexican state of Hidalgo. The blast killed at least 137 people and injured dozens more.', 2019, 1, 18, NULL, NULL, NULL, 'day', '18 January 2019', 51, 'https://en.wikipedia.org/wiki/Tlahuelilpan_pipeline_explosion'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q96609935', '2020 Oaxaca earthquake', 'An earthquake struck the Mexican state of Oaxaca at 10:29 local time on June 23, 2020, with a magnitude of 7.4 Mw. The epicenter was 19 miles (31 km) from San Miguel del Puerto and 7.5 miles (12.1 km) south-southwest of Santa María Zapotitlán.', 2020, 6, 23, NULL, NULL, NULL, 'day', '23 June 2020', 48, 'https://en.wikipedia.org/wiki/2020_Oaxaca_earthquake'),
  ('Q114052430', '2022 Western México earthquake', 'On 19 September 2022, a moment magnitude 7.6–7.7 earthquake struck between the Mexican states of Michoacán and Colima at 13:05:06 local time. The earthquake had a depth of 26.9 km (16.7 mi), resulting in a maximum intensity of VIII (Severe) on the Modified Mercalli intensity scale.', 2022, 9, 19, NULL, NULL, NULL, 'day', '19 September 2022', 43, 'https://en.wikipedia.org/wiki/2022_Michoac%C3%A1n_earthquake'),
  ('Q117320430', 'Ciudad Juárez migrant center fire', 'On 27 March 2023, a fire occurred at an immigration detention center in Ciudad Juárez, Chihuahua, Mexico, near the border with the United States. The fire killed 40 people and left 27 others seriously injured.', 2023, 3, 28, NULL, NULL, NULL, 'day', '28 March 2023', 45, 'https://en.wikipedia.org/wiki/Ciudad_Ju%C3%A1rez_migrant_center_fire');
